// Specimen alignment check: compares a part's pasted LIS specimen text (`part.lis`) against the
// specimen line generated by the form/report deck, using clinical equivalence so standard
// abbreviations and synonyms ("R tube", "right tube" <-> "Right fallopian tube, salpingectomy")
// pass cleanly while genuine laterality or organ mismatches surface in the Checks panel.

const SPELLINGS = [
  [/\bcaec/g, 'cec'],
  [/\bileo-?caec/g, 'ileocec'],
  [/\boesophag/g, 'esophag'],
  [/\btumour/g, 'tumor'],
  [/\bsterilis/g, 'steriliz'],
  [/\bhaemorrhag/g, 'hemorrhag'],
  [/\bgynaecolog/g, 'gynecolog']
];

const SIDED_ORGAN = '(?:fallopian|tubes?|ovar(?:y|ies|ian)|adnexa?e?|salping\\w*|oophor\\w*|paratubal|fimbrial|breast|mammary|axill\\w*|kidney|renal|nephrect\\w*|ureter\\w*|adrenal|thyroid|hemithyroid\\w*|parathyroid|parotid|submandibular|tonsil|testis|testicular|epididym\\w*|inguin\\w*|femoral|pelvic|iliac|obturator|neck|arm|forearm|hand|leg|thigh|calf|foot|shoulder|elbow|wrist|hip|knee|ankle|ear|eyelid|cheek|temple|frontal|temporal|parietal|occipital|fronto|temporo|parieto|occipito|cerebell\\w*|cpa\\b|cerebello-?pontine|sphenoid\\w*|thalam\\w*|upper|middle|lower|lung|bronch\\w*|pleura\\w*|colon|hemicolect\\w*|superior|inferior|medial|lateral|anterior|posterior)';
const CLOCK_SIDE = /(?<![a-z\d])([lr])t?\.?\s?(?:1[0-2]|0?[1-9])(?:\s?(?:-|\/|to)\s?(?:1[0-2]|0?[1-9]))?(?:h\b|\s?o\s?['\u2019]?\s?clock\b)/gi;
const LOBE_SIDE = /\b(r(?:ul|ml|ll)|l(?:ul|ll))\b/gi;
const SIDE_RE = new RegExp(`\\b(left|right)\\b|(?<!post-)(?<!pre-)\\b(lt|rt)\\b\\.?(?=\\s*(?:\\d|${SIDED_ORGAN}))|\\b([lr])\\b\\.?(?=\\s*${SIDED_ORGAN})`, 'gi');
const BILAT_RE = /\b(?:bilateral|bilat\.?|b\/l|both|bso|rrso|rrbso|tahbso|tlhbso|lavhbso|appendages|adnexae|ovaries|fallopian\s+tubes|tubes\s+and\s+ovaries|ovaries\s+and\s+tubes)\b/i;

/** Normalise spelling, part letters, and whitespace for clinical comparison. */
export function normaliseSpecimen(text) {
  let s = String(text || '').toLowerCase().replace(/^\s*\([a-z]\)\s*/i, '');
  for (const [re, to] of SPELLINGS) s = s.replace(re, to);
  return s.replace(/\s+/g, ' ').trim();
}

/** Extract laterality ('left' | 'right' | 'bilateral' | '') from a specimen description. */
export function extractLaterality(text) {
  const s = normaliseSpecimen(text);
  if (!s) return '';
  if (BILAT_RE.test(s)) return 'bilateral';
  const found = new Set();
  for (const m of s.matchAll(SIDE_RE)) found.add(/^l/i.test(m[1] || m[2] || m[3]) ? 'left' : 'right');
  for (const m of s.matchAll(CLOCK_SIDE)) found.add(/^l/i.test(m[1]) ? 'left' : 'right');
  for (const m of s.matchAll(LOBE_SIDE)) found.add(/^l/i.test(m[1]) ? 'left' : 'right');
  if (found.size > 1) return 'bilateral';
  return found.size === 1 ? [...found][0] : '';
}

// Clinical synonym expansion to canonical organ concepts.
const CONCEPT_RULES = [
  [/\b(?:tah|tlh|lavh|vh)\s*-?\s*bso\b/g, ' uterus cervix fallopian_tube ovary '],
  [/\b(?:salpingo-?oophorectom(?:y|ies)|bso|rrso|rrbso|adnexa?e?|appendages)\b/g, ' fallopian_tube ovary '],
  [/\b(?:fallopian\s+tubes?|salpingectom(?:y|ies)|salpinx|hydrosalpinx|paratubal|fimbrial\s+cyst|tubal\s+ligation)\b/g, ' fallopian_tube '],
  [/(?<!eustachian\s)(?<!neural\s)(?<!endotracheal\s)(?<!chest\s)(?<!peg\s)(?<!ng\s)(?<!nasogastric\s)(?<!gastrostomy\s)(?<!tracheostomy\s)\btubes?\b/g, ' fallopian_tube '],
  [/\b(?:ovar(?:y|ies|ian)|oophorectom(?:y|ies))\b/g, ' ovary '],
  [/\b(?:uterus|uterine|hysterectom(?:y|ies)|tah|tlh|lavh|myomectom(?:y|ies)|fibroids?|leiomyomas?|myomas?)\b/g, ' uterus '],
  [/\b(?:cervix|cervical|leep|lletz|cone\s+biopsy)\b/g, ' cervix '],
  [/\b(?:endometrium|endometrial|pipelle)\b/g, ' endometrium '],
  [/\b(?:stomach|gastric|gastrectom(?:y|ies)|antrum|antral|incisura|angular(?:is)?|fundus|cardia)\b/g, ' stomach '],
  [/\b(?:esophagus|esophageal|esophagectom(?:y|ies)|goj|gej)\b/g, ' esophagus '],
  [/\b(?:duodenum|duodenal)\b/g, ' duodenum '],
  [/\b(?:cecum|cecal|ileocecal|icv|ascending\s+colon|transverse\s+colon|descending\s+colon|hepatic\s+flexure|splenic\s+flexure|sigmoid|rectosigmoid|colon|colonic|colectom(?:y|ies)|hemicolectom(?:y|ies)|\b(?:ac|dc|tc|hf|sf)\b(?=\s+(?:polyp|biops|cancer|tumou?r|mass|lesion|resect|esd|emr|smt|scar|ulcer)))\b/g, ' colon '],
  [/\b(?:terminal\s+ileum|ileum|ileal|\bt\.?i\.?\b)\b/g, ' ileum '],
  [/\b(?:rectum|rectal|abdominoperineal|apr|low\s+anterior\s+resection|lar)\b/g, ' rectum '],
  [/\b(?:appendix|appendicectom(?:y|ies)|appendectom(?:y|ies))\b/g, ' appendix '],
  [/\b(?:gallbladder|cholecystectom(?:y|ies)|\bgb\b)\b/g, ' gallbladder '],
  [/\b(?:liver|hepatic|hepatectom(?:y|ies))\b/g, ' liver '],
  [/\b(?:pancreas|pancreatic|pancreatectom(?:y|ies)|pancreaticoduodenectom(?:y|ies)|whipple)\b/g, ' pancreas '],
  [/\b(?:ampulla|ampullary|periampullary)\b/g, ' ampulla '],
  [/\b(?:breast|mammary|mastectom(?:y|ies)|lumpectom(?:y|ies)|wle)\b/g, ' breast '],
  [/\b(?:lung|pulmonary|lobectom(?:y|ies)|pneumonectom(?:y|ies)|rul|rml|rll|lul|lll|lingula(?:r)?)\b/g, ' lung '],
  [/\b(?:kidney|renal|nephrectom(?:y|ies))\b/g, ' kidney '],
  [/\b(?:prostate|prostatic|prostatectom(?:y|ies)|turp)\b/g, ' prostate '],
  [/\b(?:urinary\s+bladder|bladder|turbt)\b/g, ' bladder '],
  [/\b(?:thyroid|hemithyroid(?:ectomy)?|thyroidectom(?:y|ies))\b/g, ' thyroid '],
  [/\b(?:parathyroid)\b/g, ' parathyroid '],
  [/\b(?:parotid|parotidectom(?:y|ies))\b/g, ' parotid '],
  [/\b(?:lymph\s+nodes?|sentinel\s+node|slnb?|ln|neck\s+dissection)\b/g, ' lymph_node '],
  [/\b(?:skin|cutaneous|scalp)\b/g, ' skin '],
  [/\b(?:brain|cerebral|cerebellum|cerebellar|frontal\s+lobe|temporal\s+lobe|parietal\s+lobe|occipital\s+lobe|pituitary|sellar|brainstem|cpa|cerebellopontine)\b/g, ' brain ']
];

const MAJOR_ORGANS = new Set([
  'uterus', 'cervix', 'endometrium', 'fallopian_tube', 'ovary',
  'stomach', 'esophagus', 'duodenum', 'ileum', 'colon', 'rectum', 'appendix',
  'gallbladder', 'liver', 'pancreas', 'ampulla',
  'breast', 'lung', 'kidney', 'prostate', 'bladder',
  'thyroid', 'parathyroid', 'parotid', 'lymph_node', 'skin', 'brain'
]);

/** Extract canonical major organ concepts present in a specimen string. */
export function organConcepts(text) {
  let s = ` ${normaliseSpecimen(text)} `;
  for (const [re, to] of CONCEPT_RULES) s = s.replace(re, to);
  const found = new Set();
  for (const tok of s.split(/[^a-z0-9_]+/).filter(Boolean)) {
    if (MAJOR_ORGANS.has(tok)) found.add(tok);
  }
  return found;
}

const STOP_WORDS = new Set([
  'resection', 'excision', 're', 'biopsy', 'biopsies', 'bx', 'specimen', 'tissue', 'sample',
  'mass', 'masses', 'lesion', 'lesions', 'nodule', 'nodules', 'tumor', 'tumors', 'polyp', 'polyps',
  'cyst', 'cysts', 'margin', 'margins', 'shave', 'core', 'cores', 'punch', 'curettage', 'curettings',
  'total', 'subtotal', 'simple', 'radical', 'partial', 'complete', 'benign', 'frozen', 'section', 'fs',
  'and', 'or', 'of', 'the', 'with', 'from', 'for', 'in', 'at', 'to', 'a', 'an', 'no', 'site', 'part',
  'x', 'cm', 'mm', 'g', 'left', 'right', 'bilateral', 'lt', 'rt', 'l', 'r', 'not', 'stated', 'specified',
  'sterilization', 'salpingectomy', 'oophorectomy', 'hysterectomy'
]);

function contentWords(text) {
  let s = ` ${normaliseSpecimen(text)} `;
  for (const [re, to] of CONCEPT_RULES) s = s.replace(re, to);
  return new Set(s.split(/[^a-z0-9_]+/).filter((w) => w.length >= 2 && !STOP_WORDS.has(w) && !/^\d+$/.test(w)));
}

function jumpField(schema, prefer) {
  const ids = new Set((schema?.fields || []).map((f) => f.id));
  for (const id of prefer) if (ids.has(id)) return id;
  return undefined;
}

/**
 * Check whether a part's pasted LIS specimen (`pastedLis`) aligns with the report's generated
 * specimen line (`generatedSpecimen`). Returns `{ level, message, field? }[]` (empty when aligned).
 */
export function checkSpecimenAlignment(pastedLis, generatedSpecimen, schema = null) {
  const pasted = String(pastedLis || '').trim();
  const gen = String(generatedSpecimen || '').trim();
  if (!pasted || !gen) return [];

  const issues = [];
  const pSide = extractLaterality(pasted);
  const gSide = extractLaterality(gen);

  if (pSide && gSide && pSide !== gSide) {
    const opposite = (pSide === 'left' && gSide === 'right') || (pSide === 'right' && gSide === 'left');
    issues.push({
      level: opposite ? 'error' : 'warn',
      field: jumpField(schema, ['side', 'laterality', 'specimenName']),
      message: `Specimen laterality mismatch: pasted "${pasted}" (${pSide}) vs report "${gen}" (${gSide}).`
    });
  }

  const pOrgans = organConcepts(pasted);
  const gOrgans = organConcepts(gen);

  if (pOrgans.size && gOrgans.size) {
    const shared = [...pOrgans].filter((o) => gOrgans.has(o));
    // Hysterectomy routinely prints "Uterus and cervix" even when the LIS only says "Uterus, resection".
    const implicitCervix = pOrgans.has('uterus') && !/\bsubtotal|supracervical\b/i.test(pasted);
    const missingFromGen = [...pOrgans].filter((o) => !gOrgans.has(o));
    const extraInGen = [...gOrgans].filter((o) => !pOrgans.has(o) && !(o === 'cervix' && implicitCervix));

    if (!shared.length) {
      issues.push({
        level: 'error',
        field: jumpField(schema, ['specimenName', 'site', 'organ']),
        message: `Specimen mismatch: pasted "${pasted}" vs report "${gen}". Check the specimen field or template.`
      });
    } else if (missingFromGen.length || extraInGen.length) {
      // Allow endometrial biopsy / polyp / uterus overlap without nagging when the core organ aligns.
      const benignEndoPair = pOrgans.has('endometrium') && gOrgans.has('uterus');
      const benignColorectalPair = (pOrgans.has('colon') && gOrgans.has('rectum')) || (pOrgans.has('rectum') && gOrgans.has('colon'));
      if (!benignEndoPair && !benignColorectalPair) {
        issues.push({
          level: 'warn',
          field: jumpField(schema, ['specimenName', 'attachedAdnexa', 'procedure', 'site']),
          message: `Specimen alignment: pasted "${pasted}" vs report "${gen}". Confirm the specimen matches the diagnosis line.`
        });
      }
    }
  } else if (pOrgans.size === 0 && gOrgans.size === 0) {
    const pw = contentWords(pasted);
    const gw = contentWords(gen);
    if (pw.size && gw.size && ![...pw].some((w) => gw.has(w))) {
      issues.push({
        level: 'warn',
        field: jumpField(schema, ['specimenName', 'site']),
        message: `Specimen alignment: pasted "${pasted}" vs report "${gen}". Confirm the specimen matches the diagnosis line.`
      });
    }
  }

  return issues;
}
